def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_opp = opp[-1]
    last_my = my[-1]

    total_opp_c = opp.count('C')
    total_opp_d = n - total_opp_c
    opp_rate = total_opp_c / n

    # recent windows
    w = min(12, n)
    recent = opp[-w:]
    recent_c = recent.count('C')
    recent_rate = recent_c / w

    w2 = min(4, n)
    last4 = opp[-w2:]
    last4_c = last4.count('C')

    # opponent defection streak
    def_streak = 0
    for a in reversed(opp):
        if a == 'D':
            def_streak += 1
        else:
            break

    # opponent cooperation streak
    coop_streak = 0
    for a in reversed(opp):
        if a == 'C':
            coop_streak += 1
        else:
            break

    remaining = 100 - n

    # Very endgame: exploit a cooperative opponent
    if remaining <= 2:
        if opp_rate > 0.5:
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'D'

    # Opening: cooperate to build mutual benefit
    if n <= 2:
        return 'C'

    # If opponent almost never defects, milk them but keep them cooperating
    if total_opp_d == 0:
        # avoid spoiling at bad times: defect occasionally but return to C
        if n >= 6 and n % 7 == 0 and remaining > 5:
            return 'D'
        return 'C'

    if total_opp_d == 1 and total_opp_c >= 6:
        if remaining > 3 and n % 5 == 0:
            return 'D'
        return 'C'

    # Opponent mostly cooperative overall
    if opp_rate >= 0.85:
        # punish fresh defection briefly
        if last_opp == 'D' and def_streak >= 2:
            return 'D'
        # opportunistic defection every so often
        if remaining > 4 and coop_streak >= 3 and n % 6 == 0:
            return 'D'
        return 'C'

    # Opponent mostly defective overall: defect, with rare probes
    if opp_rate <= 0.2:
        if n % 11 == 0 and remaining > 10:
            return 'C'
        return 'D'

    # Strong recent defection: retaliate
    if recent_rate <= 0.2:
        return 'D'

    # Strong recent cooperation: reciprocate, occasional probe
    if recent_rate >= 0.8:
        if last_opp == 'D' and def_streak >= 2:
            return 'D'
        if remaining > 3 and last4_c == w2 and n % 8 == 0:
            return 'D'
        return 'C'

    # If we defected and opponent still cooperated, avoid endless exploitation
    if last_my == 'D' and last_opp == 'C':
        # return to cooperation most of the time to keep them engaged
        if def_streak == 0 and rng.random() < 0.8:
            return 'C'
        if remaining > 5 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Opponent defected last: retaliate with some forgiveness for isolated cases
    if last_opp == 'D':
        if def_streak >= 3:
            return 'D'
        # isolated defection from a cooperative-ish opponent: forgive sometimes
        if def_streak == 1 and opp_rate > 0.55 and remaining > 5:
            if rng.random() < 0.45:
                return 'C'
        return 'D'

    # Opponent cooperated last
    if last_opp == 'C':
        # moderate opponent: mostly cooperate, mixed probing
        if opp_rate >= 0.5:
            if remaining > 3 and coop_streak >= 4 and rng.random() < 0.12:
                return 'D'
            return 'C'
        # less trustworthy opponent: more cautious
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    return 'C'
